#include <algorithm>

using namespace std;

class Solution {
public:
    vector<int> pathExistenceQueries(int n, vector<int>& nums, int maxDiff, vector<vector<int>>& queries) {
        vector<pair<int, int>> pairs(n);
        for (int i = 0; i < n; ++i) pairs[i] = {nums[i], i};
        sort(pairs.begin(), pairs.end());

        vector<int> sortedNums(n), indexMap(n);
        for (int i = 0; i < n; ++i) {
            sortedNums[i] = pairs[i].first;
            indexMap[pairs[i].second] = i;
        }

        int maxLevel = 0;
        while ((1 << maxLevel) <= n) maxLevel++;
        maxLevel++;

        vector<vector<int>> jump(n, vector<int>(maxLevel));
        int right = 0;
        for (int i = 0; i < n; ++i) {
            while (right + 1 < n && sortedNums[right + 1] - sortedNums[i] <= maxDiff) right++;
            jump[i][0] = right;
        }
        for (int level = 1; level < maxLevel; ++level) {
            for (int i = 0; i < n; ++i) {
                jump[i][level] = jump[jump[i][level - 1]][level - 1];
            }
        }

        vector<int> ans;
        for (const auto& q : queries) {
            int u = indexMap[q[0]], v = indexMap[q[1]];
            if (u == v) {
                ans.push_back(0);
                continue;
            }
            int l = min(u, v), r = max(u, v);
            int steps = 0;
            for (int level = maxLevel - 1; level >= 0; --level) {
                if (jump[l][level] < r) {
                    l = jump[l][level];
                    steps += (1 << level);
                }
            }
            if (jump[l][0] >= r) {
                ans.push_back(steps + 1);
            } else {
                ans.push_back(-1);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] pathExistenceQueries(int n, int[] nums, int maxDiff, int[][] queries) {
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = i;
        }
        Arrays.sort(pairs, Comparator.comparingInt(a -> a[0]));

        int[] sortedNums = new int[n];
        int[] indexMap = new int[n];
        for (int i = 0; i < n; i++) {
            sortedNums[i] = pairs[i][0];
            indexMap[pairs[i][1]] = i;
        }

        int maxLevel = 0;
        while ((1 << maxLevel) <= n) maxLevel++;
        maxLevel++;

        int[][] jump = new int[n][maxLevel];
        int right = 0;
        for (int i = 0; i < n; i++) {
            while (right + 1 < n && sortedNums[right + 1] - sortedNums[i] <= maxDiff) right++;
            jump[i][0] = right;
        }
        for (int level = 1; level < maxLevel; level++) {
            for (int i = 0; i < n; i++) {
                jump[i][level] = jump[jump[i][level - 1]][level - 1];
            }
        }

        int[] ans = new int[queries.length];
        for (int j = 0; j < queries.length; j++) {
            int u = indexMap[queries[j][0]], v = indexMap[queries[j][1]];
            if (u == v) {
                ans[j] = 0;
                continue;
            }
            int l = Math.min(u, v), r = Math.max(u, v);
            int steps = 0;
            for (int level = maxLevel - 1; level >= 0; level--) {
                if (jump[l][level] < r) {
                    l = jump[l][level];
                    steps += (1 << level);
                }
            }
            if (jump[l][0] >= r) {
                ans[j] = steps + 1;
            } else {
                ans[j] = -1;
            }
        }
        return ans;
    }
}

var pathExistenceQueries = function(n, nums, maxDiff, queries) {
    const pairs = nums.map((v, i) => [v, i]).sort((a, b) => a[0] - b[0]);
    const sortedNums = pairs.map(p => p[0]);
    const indexMap = new Array(n);
    for (let i = 0; i < n; i++) indexMap[pairs[i][1]] = i;

    let maxLevel = 0;
    while ((1 << maxLevel) <= n) maxLevel++;
    maxLevel++;

    const jump = Array.from({ length: n }, () => new Array(maxLevel).fill(0));
    let right = 0;
    for (let i = 0; i < n; i++) {
        while (right + 1 < n && sortedNums[right + 1] - sortedNums[i] <= maxDiff) right++;
        jump[i][0] = right;
    }
    for (let level = 1; level < maxLevel; level++) {
        for (let i = 0; i < n; i++) {
            jump[i][level] = jump[jump[i][level - 1]][level - 1];
        }
    }

    return queries.map(([q0, q1]) => {
        const u = indexMap[q0], v = indexMap[q1];
        if (u === v) return 0;
        let l = Math.min(u, v), r = Math.max(u, v);
        let steps = 0;
        for (let level = maxLevel - 1; level >= 0; level--) {
            if (jump[l][level] < r) {
                l = jump[l][level];
                steps += (1 << level);
            }
        }
        return jump[l][0] >= r ? steps + 1 : -1;
    });
};
